 const EXCLUDED='#a1MockRoot, #a1ExamContent, #lessonOptions, #pronunciationRoot, .dj-choices, .a1-options, .a1-theme-options, .a1-bridge-choices, .a1-example, .visual-lab-turn, #flashGerman, #germanOutput, .nepali-sound-note';
 function eligible(node){
  return node instanceof Element && node.matches('[lang="de"]')
   && !node.matches('button,input,textarea,option')
   && !node.closest(EXCLUDED) && !node.closest('[hidden]')
   && !node.closest('button,.a1-mock-review');
 }
 function apply(root){
  if(!root||typeof document==='undefined')return;
  const targets=[];
  if(root.nodeType===1&&root.matches?.('[lang="de"]'))targets.push(root);
  root.querySelectorAll?.('[lang="de"]').forEach(node=>targets.push(node));
  for(const target of targets){
   if(!eligible(target))continue;
   const german=target.textContent.trim();
   if(!german)continue;
   const previous=target.nextElementSibling;
   if(previous?.classList?.contains('nepali-sound-note')&&previous.dataset.nepaliSoundGerman===german)continue;
   if(previous?.classList?.contains('nepali-sound-note'))previous.remove();
   const note=annotation(german);
   if(!note)continue;
   note.dataset.nepaliSoundGerman=german;
   target.after(note);
  }
 }
 window.DEUTSCH_NEPALI_SOUND={guide,annotation,apply,uniqueCourseCount,curatedCount:curated.size};
 if(typeof document!=='undefined'&&typeof MutationObserver!=='undefined'){
  function start(){
   apply(document);
   const observer=new MutationObserver(mutations=>{
    const roots=new Set();
    for(const mutation of mutations){
     const node=mutation.target.nodeType===1?mutation.target:mutation.target.parentElement;
     if(node&&!node.closest?.('.nepali-sound-note'))roots.add(node);
    }
    for(const root of roots)apply(root);
   });
   observer.observe(document.body,{childList:true,characterData:true,subtree:true,attributes:true,attributeFilter:['hidden']});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});
  else start();
 }
